`src/envs/dev/infra/logs.ts`
```typescript
/**
 * dev environment — application logs bucket.
 *
 * Discovered by `chant build src/envs/dev/infra` alongside `main.ts`; its
 * exports flow into the same `dist/dev/infra/manifests.yaml`.
 *
 * `SecureBucket` already pins versioning, encryption, and the public-access
 * block unconditionally (SPEC criterion 1), so nothing here re-states them.
 * The reader identity is scoped to this bucket only — no wildcard action, no
 * wildcard resource, and no access to `myapp-assets-dev`.
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-dev";

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  // Baseline already grants s3:GetObject; writes are enumerated, not wildcarded.
  additionalActions: ["s3:PutObject"],
  // Same trust shape the environment's existing `reader` uses.
  trust: { mode: "account", accountID: "123456789012" },
  programmaticAccess: true,
  component: "logs-identity",
});
```

`src/envs/prod/infra/logs.ts`
```typescript
/**
 * prod environment — application logs bucket.
 *
 * Read this next to `../../dev/infra/logs.ts`: same shape, differing only in
 * the trust block, which matches this environment's existing `reader` (OIDC,
 * pinned to the `app/myapp` service account). Discovered by
 * `chant build src/envs/prod/infra` alongside `main.ts`.
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-prod";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  // Enumerated actions only — SPEC criterion 4 forbids wildcards on prod.
  additionalActions: ["s3:PutObject"],
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  programmaticAccess: false,
  component: "logs-identity",
});
```

No file under `src/composites/` changes, and neither `main.ts` needs editing — directory discovery picks these up.
